  function compress(file) {
    return new Promise((res, rej) => {
      const img = new Image(), url = URL.createObjectURL(file);
      img.onload = () => {
        const k = Math.min(1, 900 / Math.max(img.width, img.height));
        const cv = document.createElement('canvas');
        cv.width = img.width * k; cv.height = img.height * k;
        cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height);
        URL.revokeObjectURL(url); res(cv.toDataURL('image/jpeg', 0.72));
      };
      img.onerror = (error) => { URL.revokeObjectURL(url); rej(error); }; img.src = url;
    });
  }
  let photoGeneration = 0, photoPending = false;
  async function takeFile(file) {
    if (!file) return;
    if (!/^image\/(png|jpeg|webp|gif)$/.test(file.type) || file.size > 10000000)
      return toast(ui('รองรับรูป PNG, JPG, WebP หรือ GIF ไม่เกิน 10 MB','Use a PNG, JPG, WebP or GIF up to 10 MB'));
    const ticket = ++photoGeneration;
    photoPending = true;
    try { const src = await compress(file); if (ticket === photoGeneration && dlg.open) setPhoto(src); }
    catch { if (ticket === photoGeneration) toast(ui('อ่านไฟล์รูปไม่ได้','Could not read the photo')); }
    finally { if (ticket === photoGeneration) photoPending = false; }
  }
