  function loadReports() {
    const get = key => {
      try { const list = JSON.parse(localStorage.getItem(key)); return Array.isArray(list) ? list : []; }
      catch { return []; }
    };
    const current = get(CKEY);
    const legacy = get('rid-water-map-demo-reports').map(c => ({
      id:c.id, title:c.title, detail:c.detail, status:({new:0,in_progress:2,done:3})[c.status]??0,
      office:c.owner??'', reporter:c.reporter??'', photo:c.photo, locationNote:c.coord, dateLabel:c.date,
      note:c.note, history:c.history,
    }));
    if (!legacy.some(c=>c.id==='RID-2569-00124')) legacy.push({
      id:'RID-2569-00124', title:'สิ่งกีดขวางทางน้ำ', detail:'พบกิ่งไม้สะสมหน้าประตูระบายน้ำในกรณีตัวอย่าง',
      office:'สำนักงานชลประทานที่ 11', status:2, locationNote:'กรณีตัวอย่างในต้นแบบเดิม', history:[['รับเรื่องแล้ว','23 พ.ย. 2569 เวลา 09.10 น.']],
    });
    const unique = new Map();
    for (const c of [...current,...legacy,...RW.complaints]) {
      if (c && typeof c.id==='string' && typeof c.title==='string' && !unique.has(c.id)) unique.set(c.id,c);
    }
    return [...unique.values()];
  }
